def key(text):
    """The tuple of weights of a text: equal tuples are equal texts, and tuples sort the way the texts do."""
    out = []
    for ch in text:
        out.extend(WEIGHTS[ch])
    return tuple(out)


def compare(a, b):
    x, y = key(a), key(b)
    return (x > y) - (x < y)
